export const SHEET_URL='https://docs.google.com/spreadsheets/d/1tqoUkGDgs6IVVPab999_zvo3rwiY95VibYmb69fLHBk/edit?gid=1059632877';
export const LEAD_STATUSES={new:'Nuevo',contacted:'Contactado',proposal:'Propuesta',won:'Ganado',lost:'Perdido'};
export const POST_STATUSES={draft:'Borrador',review:'En revisión',approved:'Aprobado',scheduled:'Programado local'};
const KEY='ornat-control-v1';
const MAX_BYTES=8*1024*1024;
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
export const emptyState=()=>({version:1,leads:[],publications:[],usage:[],events:[],activity:[],tasks:[],quotes:[],conversations:[],enrollments:[],settings:{analyticsConsent:false,sheetUrl:SHEET_URL,savedViews:[],lastBackupAt:'',...defaultSettings2()}});
const text=(v,max=1000)=>String(v??'').slice(0,max);
/** Pertenencia segura a un mapa de enumeración: solo claves propias y de tipo texto (nada de constructor, toString, __proto__). */
export const inMap=(map,key)=>typeof key==='string'&&Object.hasOwn(map,key);
const EMAIL=/^[\p{L}\p{N}._+-]{1,64}@[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?(?:\.[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?)+$/u;
/** Correo normalizado (recortado) o '' si está vacío. Lanza si trae ?&#% o espacios, o no tiene forma de correo. */
export function cleanEmail(v){const s=String(v??'').trim();if(!s)return '';if(s.length>250||!EMAIL.test(s))throw new Error('El correo no es válido: usa el formato nombre@dominio.com, sin espacios ni los símbolos ? & # %.');return s;}
// Al leer datos ya guardados o respaldos viejos, un correo que hoy no pasa la validación se vacía en vez de bloquear todo el panel.
function lenientLead(item){try{return cleanLead(item);}catch(error){if(item&&typeof item==='object'&&!isValidEmail(item.email))return cleanLead({...item,email:''});throw error;}}
export const isValidEmail=v=>{try{return cleanEmail(v)!=='';}catch{return false;}};
function object(v){return v&&typeof v==='object'&&!Array.isArray(v);}
function date(v,required=false){if(!v&&!required)return '';if(typeof v!=='string'||Number.isNaN(Date.parse(v)))throw new Error('Una fecha no es válida.');return new Date(v).toISOString();}
function safeURL(value){if(value==='')return true;try{const url=new URL(value);return url.protocol==='https:'&&!/[\u0000-\u0020\\]/.test(value);}catch{return false;}}
function checkKeys(value,depth=0){if(depth>12)throw new Error('Demasiados niveles en el archivo.');if(!object(value)&&!Array.isArray(value))return;for(const [key,item]of Object.entries(value)){if(['__proto__','prototype','constructor'].includes(key))throw new Error('Clave no permitida por seguridad.');checkKeys(item,depth+1);}}
function uniqueIds(items){const seen=new Set(),reserved=new Set(items.map(item=>item.id));return items.map(item=>{let id=item.id,n=1;if(!id||seen.has(id)){const base=text(id||'record',175);do{id=`${base}-recovered-${n++}`;}while(reserved.has(id));reserved.add(id);}seen.add(id);return id===item.id?item:{...item,id};});}
const backupJSON=state=>JSON.stringify({format:'ornat-control',version:1,exportedAt:new Date().toISOString(),state});
function tokens(value){if(value===undefined||value===null||(typeof value==='string'&&value.trim()===''))return null;const n=Number(value);if(!Number.isSafeInteger(n)||n<0)throw new Error('Los tokens deben ser enteros positivos o cero. Deja vacío si no lo sabes.');return n;}
export const CHANNELS=['Sitio web','Instagram','WhatsApp','Facebook','LinkedIn','Referido','Evento','Otro','Google'];
export const PRIORITIES={alta:'Alta',media:'Media',baja:'Baja'};
export const TIMELINE_TYPES={note:'Nota',call:'Llamada',email:'Correo',meeting:'Reunión',whatsapp:'WhatsApp',stage:'Cambio de etapa'};
export const OPEN_STATUSES=['new','contacted','proposal'];
export const MAX_TIMELINE=200,MAX_TAGS=12,MAX_VIEWS=20;
const fold=s=>String(s??'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
function money(v){if(v===undefined||v===null||(typeof v==='string'&&v.trim()===''))return null;const n=typeof v==='number'?v:Number(String(v).trim());if(!Number.isSafeInteger(n)||n<0||n>1e12)throw new Error('El valor debe ser un entero en MXN igual o mayor que cero. Deja vacío si aún no lo sabes.');return n;}
function cleanTags(v){if(v===undefined||v===null||v==='')return [];if(!Array.isArray(v))throw new Error('Las etiquetas no son válidas.');if(v.length>MAX_TAGS)throw new Error(`Usa hasta ${MAX_TAGS} etiquetas por contacto.`);const out=[];for(const t of v){const s=String(t??'').trim();if(!s)continue;if(s.length>30)throw new Error('Cada etiqueta admite hasta 30 caracteres.');if(!out.some(x=>fold(x)===fold(s)))out.push(s);}return out;}
function cleanTimeline(v){if(v===undefined||v===null)return [];if(!Array.isArray(v))throw new Error('La línea de tiempo no es válida.');if(v.length>MAX_TIMELINE)throw new Error(`La línea de tiempo admite hasta ${MAX_TIMELINE} entradas.`);return v.map(e=>{if(!object(e))throw new Error('Una entrada de la línea de tiempo no es válida.');if(!inMap(TIMELINE_TYPES,e.type))throw new Error('Tipo de entrada no válido en la línea de tiempo.');const t=String(e.text??'').trim();if(!t)throw new Error('Cada entrada de la línea de tiempo necesita texto.');return {id:text(e.id||uid(),200),at:date(e.at,true),type:e.type,text:text(t,2000),...(e.stage?{stage:text(e.stage,90)}:{})};});}
export function cleanLead(item){if(!object(item)||!String(item.name||'').trim())throw new Error('Cada contacto necesita un nombre.');const status=item.status||'new';if(!inMap(LEAD_STATUSES,status))throw new Error('Estado del contacto no válido.');const channel=item.channel===undefined||item.channel===null?'':String(item.channel);if(channel&&!CHANNELS.includes(channel))throw new Error('Canal no válido.');const priority=item.priority||'media';if(!inMap(PRIORITIES,priority))throw new Error('Prioridad no válida: usa alta, media o baja.');return {id:text(item.id||uid(),200),name:text(item.name,150),company:text(item.company,150),email:cleanEmail(item.email),phone:text(item.phone,80),status,notes:text(item.notes,30000),source:text(item.source||'manual',200),createdAt:date(item.createdAt)||new Date().toISOString(),updatedAt:date(item.updatedAt)||new Date().toISOString(),channel,owner:text(item.owner,100).trim(),tags:cleanTags(item.tags),priority,value:money(item.value),projectType:text(item.projectType,100).trim(),nextAction:text(item.nextAction,300),nextActionAt:date(item.nextActionAt),lastContactAt:date(item.lastContactAt),lostReason:text(item.lostReason,500),timeline:cleanTimeline(item.timeline),pipeline:text(item.pipeline||'venta',40).trim()||'venta',stageId:text(item.stageId,40).trim(),lastReplyAt:date(item.lastReplyAt)};}
function cleanPost(item){if(!object(item)||!String(item.title||'').trim())throw new Error('Cada publicación necesita un título.');const status=item.status||'draft';if(!inMap(POST_STATUSES,status))throw new Error('Estado de publicación no válido: solo borrador, revisión, aprobado o programado local.');const calendar=item.calendar?cleanCalendar(item.calendar):undefined;return {id:text(item.id||uid(),200),title:text(item.title,200),channel:text(item.channel||'Sin especificar',100),content:text(item.content,30000),scheduledAt:date(item.scheduledAt),status,approvedAt:date(item.approvedAt),notes:text(item.notes,10000),source:text(item.source||'manual',200),createdAt:date(item.createdAt)||new Date().toISOString(),sheetId:text(item.sheetId,200),sheetStatus:text(item.sheetStatus,200),format:text(item.format,200),hashtags:text(item.hashtags,5000),asset:text(item.asset,2000),...(calendar?{calendar}:{})};}
function cleanCalendar(item){if(!object(item)||!item.id||!item.expectedVersion)throw new Error('La referencia de revisión de calendario no es válida.');if(item.decision&&!['approve','reject'].includes(item.decision))throw new Error('La decisión de revisión no es válida.');return {id:text(item.id,200),rowNumber:Number.isSafeInteger(item.rowNumber)?item.rowNumber:0,expectedState:text(item.expectedState,1000),expectedVersion:text(item.expectedVersion,2000),spreadsheetId:text(item.spreadsheetId,300),sheetId:text(item.sheetId,300),decision:text(item.decision,20),reviewer:text(item.reviewer,200)};}
function cleanUsage(item){if(!object(item))throw new Error('Registro de tokens no válido.');const scope=item.scope||'backend';if(!['frontend','backend'].includes(scope))throw new Error('Indica frontend o backend.');const source=item.source||'manual';if(!['manual','csv','json','instrumented'].includes(source))throw new Error('La procedencia del consumo no es válida.');return {id:text(item.id||uid(),200),date:date(item.date)||new Date().toISOString(),provider:text(item.provider,100),model:text(item.model||'Sin especificar',150),inputTokens:tokens(item.inputTokens),outputTokens:tokens(item.outputTokens),scope,source,reference:text(item.reference,1000)};}
export function normalizeHeatEvent(input,consent){if(!consent)throw new Error('Activa el consentimiento local antes de registrar eventos.');if(!object(input)||!input.page||!String(input.template||'').trim())throw new Error('El evento necesita página y plantilla.');for(const key of ['x','y'])if(typeof input[key]!=='number'||!Number.isFinite(input[key])||input[key]<0||input[key]>1)throw new Error('Las coordenadas deben estar normalizadas entre 0 y 1.');for(const key of ['viewportWidth','viewportHeight'])if(!Number.isFinite(input[key])||input[key]<1||input[key]>16000)throw new Error('El tamaño del viewport no es válido.');if(!['click','pointer'].includes(input.eventType||'click'))throw new Error('Tipo de evento no admitido.');return {id:text(input.id||(input.timestamp?eventIdentity(input):uid()),200),page:text(input.page,500),template:text(input.template,200),x:input.x,y:input.y,viewportWidth:Math.round(input.viewportWidth),viewportHeight:Math.round(input.viewportHeight),eventType:input.eventType||'click',timestamp:date(input.timestamp)||new Date().toISOString()};}
export function validateState(input,{lenient=false}={}){checkKeys(input);if(!object(input))throw new Error('El respaldo no contiene datos válidos.');const state=emptyState();for(const key of ['leads','publications','usage','events','activity','tasks','quotes','conversations','enrollments']){if(input[key]!==undefined&&!Array.isArray(input[key]))throw new Error(`La lista ${key} no es válida.`);if((input[key]||[]).length>(key==='events'?10000:key==='tasks'||key==='conversations'?20000:key==='enrollments'?10000:5000))throw new Error('El respaldo contiene demasiados registros.');}state.leads=(input.leads||[]).map(lenient?lenientLead:cleanLead);state.publications=(input.publications||[]).map(cleanPost);state.usage=(input.usage||[]).map(cleanUsage);state.settings={analyticsConsent:input.settings?.analyticsConsent===true,sheetUrl:input.settings?.sheetUrl||SHEET_URL,savedViews:cleanViews(input.settings?.savedViews),lastBackupAt:date(input.settings?.lastBackupAt),...(input.settings?.calendarSource?{calendarSource:cleanSource(input.settings.calendarSource)}:{}),...cleanSettings2(input.settings)};if(!safeURL(state.settings.sheetUrl)){if(lenient)state.settings.sheetUrl=SHEET_URL;else throw new Error('La URL de la hoja debe usar HTTPS.');}state.events=(input.events||[]).map(e=>normalizeHeatEvent(e,true));state.activity=(input.activity||[]).map(a=>({id:text(a.id||uid(),200),timestamp:date(a.timestamp,true),action:text(a.action,300),detail:text(a.detail,1000),source:text(a.source||'local',100)}));state.tasks=(input.tasks||[]).map(cleanTask);state.quotes=(input.quotes||[]).map(cleanQuote);state.conversations=(input.conversations||[]).map(cleanConversation);state.enrollments=(input.enrollments||[]).map(cleanEnrollment);for(const key of ['leads','publications','usage','events','activity','tasks','quotes','conversations','enrollments'])state[key]=uniqueIds(state[key]);state.settings.savedViews=uniqueIds(state.settings.savedViews);state.settings.templates=uniqueIds(state.settings.templates);state.settings.sequences=uniqueIds(state.settings.sequences);return state;}
export function createStore(adapter){const storage=adapter||globalThis.localStorage;if(!storage)throw new Error('Tu navegador no permite guardar este panel. Usa un navegador con almacenamiento local.');const get=()=>{let raw;try{raw=storage.getItem(KEY);}catch{throw new Error('No se puede acceder al almacenamiento local.');}if(!raw)return emptyState();try{return validateState(JSON.parse(raw),{lenient:true});}catch(error){throw new Error(`No se pudo leer el panel guardado: ${error.message} Descarga o conserva tus datos antes de borrar el almacenamiento.`);}};const write=state=>{const json=JSON.stringify(state);if(new TextEncoder().encode(backupJSON(state)).byteLength>MAX_BYTES)throw new Error('El panel supera 8 MB. Exporta un respaldo y elimina eventos antiguos.');try{storage.setItem(KEY,json);}catch{throw new Error('No se pudo guardar: falta espacio o el navegador bloquea el almacenamiento. Exporta un respaldo.');}return state;};return {get,commit(action,mutate,detail='',source='local'){const candidate=get();mutate(candidate);candidate.activity.unshift({id:uid(),timestamp:new Date().toISOString(),action:text(action,300),detail:text(detail,1000),source:text(source,100)});candidate.activity=candidate.activity.slice(0,2000);return write(validateState(candidate));},replace(state,action='Importar respaldo'){const candidate=validateState(state);candidate.activity.unshift({id:uid(),timestamp:new Date().toISOString(),action:text(action,300),detail:'Se reemplazó el contenido del panel en este navegador.',source:'local'});return write(candidate);}};}
export function usageSummary(records){const sum=items=>({input:items.some(x=>x.inputTokens!==null&&x.inputTokens!==undefined)?items.reduce((s,x)=>s+(x.inputTokens??0),0):null,output:items.some(x=>x.outputTokens!==null&&x.outputTokens!==undefined)?items.reduce((s,x)=>s+(x.outputTokens??0),0):null,unknownInput:items.filter(x=>x.inputTokens===null||x.inputTokens===undefined).length,unknownOutput:items.filter(x=>x.outputTokens===null||x.outputTokens===undefined).length,count:items.length});return {...sum(records),frontend:sum(records.filter(x=>x.scope==='frontend')),backend:sum(records.filter(x=>x.scope==='backend'))};}
export function transitionPublication(post,next){if(!inMap(POST_STATUSES,next))throw new Error('Estado de publicación no válido.');if(next==='approved'&&!['review','approved'].includes(post.status))throw new Error('Envía primero el contenido a revisión antes de aprobar.');if(next==='scheduled'&&!['approved','scheduled'].includes(post.status))throw new Error('Necesitas aprobar el contenido antes de programarlo.');if(next==='scheduled'&&!post.scheduledAt)throw new Error('Selecciona una fecha antes de programar.');return {...post,status:next,approvedAt:next==='approved'?new Date().toISOString():['draft','review'].includes(next)?'':post.approvedAt};}
export function exportBackup(state){return backupJSON(validateState(state));}
export function importBackup(raw){if(typeof raw!=='string'||new TextEncoder().encode(raw).byteLength>MAX_BYTES)throw new Error('El respaldo supera 8 MB.');let parsed;try{parsed=JSON.parse(raw);}catch{throw new Error('El archivo no es JSON válido.');}checkKeys(parsed);if(parsed?.format!=='ornat-control'||parsed.version!==1)throw new Error('Formato o versión de respaldo no compatible.');return validateState(parsed.state,{lenient:true});}
export function parseCSV(raw){if(typeof raw!=='string'||raw.length>MAX_BYTES)throw new Error('El CSV supera 8 MB.');raw=raw.replace(/^﻿/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<raw.length;i++){const c=raw[i];if(c==='"'){if(quoted&&raw[i+1]==='"'){cell+='"';i++;}else if(quoted)quoted=false;else if(cell==='')quoted=true;else cell+=c;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&raw[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('El CSV tiene comillas sin cerrar.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)throw new Error('El CSV está vacío.');const headers=rows.shift().map((x,i)=>(x.replace(/^\uFEFF/,'').trim()||`Columna ${i+1}`));if(new Set(headers).size!==headers.length)throw new Error('Las columnas del CSV necesitan nombres únicos.');if(rows.length>5000)throw new Error('Importa hasta 5000 filas por archivo.');return {headers,rows};}
export function mapCSV(csv,mapping,kind){const read=(row,key)=>{const index=csv.headers.indexOf(mapping[key]);return index<0?'':row[index]||'';};return csv.rows.map((row,index)=>{try{if(kind==='leads')return mapLeadRow(read,row);if(kind==='publications'){const sheetStatus=read(row,'sheetStatus');return cleanPost({sheetId:read(row,'sheetId'),title:read(row,'title'),content:read(row,'content'),channel:read(row,'channel'),scheduledAt:read(row,'scheduledAt')||cancunDate(read(row,'scheduledDate'),read(row,'scheduledTime')),sheetStatus,status:localSheetStatus(sheetStatus),hashtags:read(row,'hashtags'),format:read(row,'format'),asset:read(row,'asset'),notes:read(row,'notes'),source:'csv'});}if(kind==='usage')return cleanUsage({date:read(row,'date'),provider:read(row,'provider'),model:read(row,'model'),inputTokens:read(row,'inputTokens'),outputTokens:read(row,'outputTokens'),scope:read(row,'scope')||'backend',source:'csv',reference:'Importación CSV declarada por el usuario'});throw new Error('Tipo de importación no válido.');}catch(error){throw new Error(`Fila ${index+2}: ${error.message}`);}});}
function localSheetStatus(value){return /revisi[oó]n|aprob|program|publicad/i.test(value)?'review':'draft';}
function cancunDate(day,time=''){if(!day)return '';let base=String(day).trim();const dmy=base.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(dmy)base=`${dmy[3]}-${dmy[2].padStart(2,'0')}-${dmy[1].padStart(2,'0')}`;if(!/^\d{4}-\d{2}-\d{2}$/.test(base))return date(base,true);let clock=String(time||'00:00').trim();const match=clock.match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/i);if(!match)throw new Error('La hora debe usar HH:MM.');let hour=Number(match[1]);if(match[3])hour=hour%12+(match[3].toUpperCase()==='PM'?12:0);if(hour>23||Number(match[2])>59)throw new Error('La hora no es válida.');return date(`${base}T${String(hour).padStart(2,'0')}:${match[2]}:00-05:00`,true);}
function cleanSource(source){if(!object(source)||!source.spreadsheetId||source.sheetId===undefined||source.sheetId===null||String(source.sheetId)==='')throw new Error('La fuente de calendario necesita spreadsheetId y sheetId.');return {spreadsheetId:text(source.spreadsheetId,300),sheetId:text(source.sheetId,300),headers:Array.isArray(source.headers)?source.headers.map(x=>text(x,200)).slice(0,100):[],importedAt:date(source.importedAt)||new Date().toISOString()};}
export function importCalendarSnapshot(raw){if(typeof raw!=='string'||raw.length>MAX_BYTES)throw new Error('El calendario supera 8 MB.');let input;try{input=JSON.parse(raw);}catch{throw new Error('El calendario no es JSON válido.');}checkKeys(input);if(input?.format!=='ornat-calendar'||input.version!==1||!Array.isArray(input.rows)||input.rows.length>5000)throw new Error('Formato de calendario no compatible.');const source=cleanSource(input),warnings=Array.isArray(input.warnings)?input.warnings.map(x=>text(x,500)):[],posts=[],ids=new Set();for(const row of input.rows){if(!row?.id){warnings.push(`Fila ${row?.rowNumber||'?'} omitida: falta ID.`);continue;}if(ids.has(String(row.id))){warnings.push(`ID duplicado ${text(row.id,100)} omitido.`);continue;}if(!object(row.values)||!row.expectedVersion){warnings.push(`Fila ${row.rowNumber||'?'} omitida: falta versión de revisión.`);continue;}const v=row.values,title=String(v['Título']||v.Titulo||v.Pieza||'').trim();if(!title){warnings.push(`ID ${text(row.id,100)} omitido: falta título.`);continue;}ids.add(String(row.id));const notes=['Pieza','Tipo','Duración real (s)','Duración recomendada','Alerta','Aprobado por','Aprobado el','Resultado','Publicado el'].filter(k=>v[k]!==undefined&&v[k]!=='').map(k=>`${k}: ${v[k]}`).join('\n');posts.push(cleanPost({title,channel:v.Red||'',content:v.Copy||'',hashtags:v.Hashtags||'',format:v.Formato||'',asset:v.Archivo||'',sheetId:row.id,sheetStatus:v.Estado||row.expectedState,status:localSheetStatus(v.Estado||row.expectedState),scheduledAt:cancunDate(v.Fecha||'',v.Hora||''),source:'calendar-json',notes,calendar:{id:row.id,rowNumber:row.rowNumber,expectedState:row.expectedState,expectedVersion:row.expectedVersion,spreadsheetId:source.spreadsheetId,sheetId:source.sheetId}}));}return {source,posts,warnings};}
export function calendarReviews(posts,source){const clean=cleanSource(source);const reviews=posts.filter(p=>p.calendar?.decision&&p.calendar.spreadsheetId===clean.spreadsheetId&&p.calendar.sheetId===clean.sheetId).map(p=>{const c=cleanCalendar(p.calendar);if(!c.reviewer.trim())throw new Error('Cada decisión necesita el nombre de quien revisó.');return {id:c.id,expectedState:c.expectedState,expectedVersion:c.expectedVersion,decision:c.decision,reviewer:c.reviewer};});if(!reviews.length)throw new Error('No hay decisiones locales listas para exportar a esta hoja.');return {format:'ornat-calendar-review',version:1,spreadsheetId:clean.spreadsheetId,sheetId:clean.sheetId,reviews};}
export function recordActivity(action,detail='',source='cms'){return createStore().commit(action,s=>{},detail,source);}
export function recordAnalyticsEvent(event){const store=createStore(),state=store.get(),normalized=normalizeHeatEvent(event,state.settings.analyticsConsent);return store.commit('Registrar interacción',s=>{if(!s.events.some(e=>e.id===normalized.id))s.events.push(normalized);s.events=s.events.slice(-10000);},`${normalized.template} · ${normalized.page}`);}


function eventIdentity(event){const raw=JSON.stringify([event.page,event.template,event.x,event.y,event.viewportWidth,event.viewportHeight,event.eventType||'click',event.timestamp]);let hash=2166136261;for(let i=0;i<raw.length;i++){hash^=raw.charCodeAt(i);hash=Math.imul(hash,16777619);}return `event-${(hash>>>0).toString(36)}`;}

// ───────────────────────── CRM: fechas, filtros, orden, duplicados, historial ─────────────────────────
export const SORTS={recent:'Más reciente',name:'Nombre A–Z',value:'Mayor valor',followup:'Próximo seguimiento',activity:'Última actividad'};
export const SORT_KEYS=['recent','name','value','followup','activity','stage','priority','channel','owner','score'];
let scoreGetter=()=>null;export const setScoreGetter=fn=>{scoreGetter=typeof fn==='function'?fn:()=>null;};
export const FOLLOW_UPS={overdue:'Vencido',today:'Hoy',week:'Próximos 7 días',none:'Sin fecha'};
export const NONE='__none';
const pad=n=>String(n).padStart(2,'0');
const DAY=/^(\d{4})-(\d{2})-(\d{2})$/;
export const dayKey=value=>{const d=new Date(value);return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;};
export function dayToISO(key){const m=DAY.exec(key||'');if(!m)return '';const d=new Date(+m[1],+m[2]-1,+m[3],12);return Number.isNaN(d.getTime())||dayKey(d)!==key?'':d.toISOString();}
export function addDays(key,n){const m=DAY.exec(key);if(!m)return '';return dayKey(new Date(+m[1],+m[2]-1,+m[3]+n,12));}
export function weekStart(now=new Date()){const d=new Date(now);d.setDate(d.getDate()-((d.getDay()+6)%7));return dayKey(d);}
export function parseLooseDate(value){const s=String(value??'').trim();if(!s)return '';let m=DAY.exec(s);if(m){const iso=dayToISO(s);if(!iso)throw new Error(`Fecha no válida: «${text(s,40)}».`);return iso;}m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(m){const iso=dayToISO(`${m[3]}-${pad(m[2])}-${pad(m[1])}`);if(!iso)throw new Error(`Fecha no válida: «${text(s,40)}».`);return iso;}if(Number.isNaN(Date.parse(s)))throw new Error(`Fecha no válida: «${text(s,40)}».`);return new Date(s).toISOString();}

export const defaultFilters=()=>({q:'',stages:[],channel:'',owner:'',priority:'',tag:'',minValue:'',maxValue:'',createdFrom:'',createdTo:'',followUp:'',sort:'recent',pipeline:'',stageIds:[],minScore:''});
