  if(f.pipeline&&(l.pipeline||'venta')!==f.pipeline)return false;
  if(f.stages.length&&!f.stages.includes(l.status))return false;
  if(f.stageIds.length&&!f.stageIds.includes(l.stageId||l.status))return false;
  if(f.minScore!==''&&(scoreGetter(l)??0)<f.minScore)return false;
  if(f.channel&&(f.channel===NONE?l.channel!=='':l.channel!==f.channel))return false;
  if(f.owner&&(f.owner===NONE?l.owner!=='':l.owner!==f.owner))return false;
  if(f.priority&&l.priority!==f.priority)return false;
  if(tag&&!l.tags.some(t=>fold(t)===tag))return false;
  if(min!==''&&(l.value===null||l.value<min))return false;
  if(max!==''&&(l.value===null||l.value>max))return false;
  if(f.createdFrom||f.createdTo){const k=dayKey(l.createdAt);if(f.createdFrom&&k<f.createdFrom)return false;if(f.createdTo&&k>f.createdTo)return false;}
