export function lastActivityAt(l){let t=l.updatedAt||l.createdAt;if(l.lastContactAt&&l.lastContactAt>t)t=l.lastContactAt;for(const e of l.timeline||[])if(e.at>t)t=e.at;return t;}
const STAGE_ORDER=Object.keys(LEAD_STATUSES),PRI_ORDER={alta:0,media:1,baja:2};
const collator=new Intl.Collator('es',{sensitivity:'base',numeric:true});
