 const root=i=>{while(parent[i]!==i){parent[i]=parent[parent[i]];i=parent[i];}return i;};
 const join=(a,b)=>{a=root(a);b=root(b);if(a!==b)parent[Math.max(a,b)]=Math.min(a,b);};
 rows.forEach((lead,i)=>{for(const key of [normEmail(lead.email)&&`e:${normEmail(lead.email)}`,phoneKey(lead.phone)&&`p:${phoneKey(lead.phone)}`]){if(!key)continue;if(keys.has(key))join(i,keys.get(key));else keys.set(key,i);}});
 const groups=new Map();rows.forEach((lead,i)=>{const key=root(i);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(i);});
