  if(!members.some(i=>i>=existing.length))continue;
  const representative=members[0],match=rows[representative];
  if(representative>=existing.length)fresh.push(match);
  for(const i of members){if(i===representative)continue;if(i<existing.length)existingMerges.push({incoming:rows[i],match});else duplicates.push({incoming:rows[i],match});}
