export const TEMPLATE_CHANNELS={email:'Correo',whatsapp:'WhatsApp'};
export const ENROLLMENT_STATUSES={active:'Activa',paused:'Pausada',completed:'Completada',exited:'Terminada'};
export const SCORE_RULE_KEYS=['channel','value','priority','recency','response','property','stage'];
export const DEFAULT_SCORE_RULES=()=>({channel:{on:true,weight:10},value:{on:true,weight:20},priority:{on:true,weight:10},recency:{on:true,weight:20},response:{on:true,weight:15},property:{on:true,weight:10},stage:{on:true,weight:15}});
