export const DEFAULT_ISSUER=()=>({name:'ORNAT',email:'',phone:'',address:'',taxId:''});
function defaultSettings2(){return {pipelines:DEFAULT_PIPELINES(),templates:DEFAULT_TEMPLATES(),sequences:DEFAULT_SEQUENCES(),scoreRules:DEFAULT_SCORE_RULES(),quoteSeq:{},issuer:DEFAULT_ISSUER()};}
const int01=(v,lo,hi,label)=>{const n=Number(v);if(!Number.isFinite(n)||n<lo||n>hi)throw new Error(`${label} debe estar entre ${lo} y ${hi}.`);return Math.round(n);};

/** Etapa base (Nuevo/Contactado/Propuesta/Ganado/Perdido) que le corresponde a una etapa del pipeline. */
export function baseStatusFor(stages,id){const st=stages.find(s=>s.id===id);if(!st)return 'new';if(st.kind==='won')return 'won';if(st.kind==='lost')return 'lost';const open=stages.filter(s=>s.kind==='open'),i=open.findIndex(s=>s.id===id);return i<=0?'new':(i===open.length-1&&open.length>=3?'proposal':'contacted');}
function cleanStage(st){if(!object(st))throw new Error('Una etapa no es válida.');const kind=st.kind||'open';if(!inMap(STAGE_KINDS,kind))throw new Error('Tipo de etapa no válido.');const id=text(st.id,40).trim();if(!SLUG.test(id))throw new Error('Cada etapa necesita un identificador válido.');const name=text(st.name,40).trim();if(!name)throw new Error('Cada etapa necesita un nombre.');const prob=kind==='won'?100:kind==='lost'?0:int01(st.prob??10,0,100,'La probabilidad');const color=HEX.test(st.color||'')?st.color.toLowerCase():'#b7c19f';return {id,name,prob,kind,color};}
export function cleanPipelines(list){if(list===undefined||list===null)return DEFAULT_PIPELINES();if(!Array.isArray(list)||!list.length||list.length>8)throw new Error('Configura entre 1 y 8 pipelines.');const ids=new Set();return list.map(p=>{if(!object(p))throw new Error('Un pipeline no es válido.');const id=text(p.id,40).trim();if(!SLUG.test(id))throw new Error('Cada pipeline necesita un identificador válido.');if(ids.has(id))throw new Error('Hay pipelines repetidos.');ids.add(id);const name=text(p.name,40).trim();if(!name)throw new Error('Cada pipeline necesita un nombre.');if(!Array.isArray(p.stages)||p.stages.length<3||p.stages.length>12)throw new Error('Cada pipeline necesita entre 3 y 12 etapas.');const sids=new Set(),stages=p.stages.map(cleanStage);for(const s of stages){if(sids.has(s.id))throw new Error('Hay etapas repetidas dentro de un pipeline.');sids.add(s.id);}for(const k of ['open','won','lost'])if(!stages.some(s=>s.kind===k))throw new Error(`El pipeline «${name}» necesita al menos una etapa ${STAGE_KINDS[k].toLowerCase()}.`);return {id,name,stages};});}
function cleanScoreRules(v){const out=DEFAULT_SCORE_RULES();if(v===undefined||v===null)return out;if(!object(v))throw new Error('Las reglas de puntaje no son válidas.');for(const k of Object.keys(v))if(!SCORE_RULE_KEYS.includes(k))throw new Error('Regla de puntaje desconocida.');for(const k of SCORE_RULE_KEYS)if(v[k]!==undefined){if(!object(v[k]))throw new Error('Una regla de puntaje no es válida.');out[k]={on:v[k].on!==false,weight:int01(v[k].weight??out[k].weight,0,50,'El peso de la regla')};}return out;}
function cleanTemplate(t){if(!object(t))throw new Error('Una plantilla no es válida.');const name=text(t.name,80).trim();if(!name)throw new Error('Cada plantilla necesita un nombre.');if(!inMap(TEMPLATE_CHANNELS,t.channel))throw new Error('Canal de plantilla no válido.');const body=text(t.body,4000);if(!body.trim())throw new Error('Cada plantilla necesita un mensaje.');return {id:text(t.id||uid(),100),name,channel:t.channel,subject:t.channel==='email'?text(t.subject,200):'',body};}
function cleanTemplates(v){if(v===undefined||v===null)return DEFAULT_TEMPLATES();if(!Array.isArray(v)||v.length>100)throw new Error('Puedes guardar hasta 100 plantillas.');return v.map(cleanTemplate);}
function cleanSequence(sq){if(!object(sq))throw new Error('Una secuencia no es válida.');const name=text(sq.name,80).trim();if(!name)throw new Error('Cada secuencia necesita un nombre.');if(!Array.isArray(sq.steps)||!sq.steps.length||sq.steps.length>20)throw new Error('Cada secuencia necesita entre 1 y 20 pasos.');return {id:text(sq.id||uid(),100),name,description:text(sq.description,300),steps:sq.steps.map(s=>{if(!object(s))throw new Error('Un paso no es válido.');const title=text(s.title,200).trim();if(!title)throw new Error('Cada paso necesita un título.');const type=s.type||'call';if(!inMap(TASK_TYPES,type))throw new Error('Tipo de tarea no válido en un paso.');return {id:text(s.id||uid(),100),wait:int01(s.wait??0,0,90,'La espera'),title,type,templateId:text(s.templateId,100)};})};}
function cleanSequences(v){if(v===undefined||v===null)return DEFAULT_SEQUENCES();if(!Array.isArray(v)||v.length>30)throw new Error('Puedes guardar hasta 30 secuencias.');return v.map(cleanSequence);}
function cleanQuoteSeq(v){if(v===undefined||v===null)return {};if(!object(v))throw new Error('La numeración de cotizaciones no es válida.');const out={};for(const [k,n] of Object.entries(v)){if(!/^\d{4}$/.test(k)||!Number.isSafeInteger(n)||n<0||n>999999)throw new Error('La numeración de cotizaciones no es válida.');out[k]=n;}return out;}
function cleanIssuer(v){const d=DEFAULT_ISSUER();if(!object(v))return d;return {name:text(v.name||d.name,120).trim()||d.name,email:text(v.email,250).trim(),phone:text(v.phone,80).trim(),address:text(v.address,300).trim(),taxId:text(v.taxId,40).trim()};}
function cleanSettings2(s){const x=object(s)?s:{};return {pipelines:cleanPipelines(x.pipelines),templates:cleanTemplates(x.templates),sequences:cleanSequences(x.sequences),scoreRules:cleanScoreRules(x.scoreRules),quoteSeq:cleanQuoteSeq(x.quoteSeq),issuer:cleanIssuer(x.issuer)};}

export function cleanTask(t){if(!object(t))throw new Error('Una tarea no es válida.');const title=text(t.title,200).trim();if(!title)throw new Error('Cada tarea necesita un título.');const type=t.type||'other';if(!inMap(TASK_TYPES,type))throw new Error('Tipo de tarea no válido.');const priority=t.priority||'media';if(!inMap(PRIORITIES,priority))throw new Error('Prioridad de tarea no válida.');const dur=t.durationMin===undefined||t.durationMin===''?30:int01(t.durationMin,5,1440,'La duración');return {id:text(t.id||uid(),200),title,type,dueAt:date(t.dueAt,true),durationMin:dur,leadId:text(t.leadId,200),owner:text(t.owner,100).trim(),priority,done:t.done===true,doneAt:t.done===true?date(t.doneAt)||new Date().toISOString():'',notes:text(t.notes,2000),source:['manual','sequence','intake','quote'].includes(t.source)?t.source:'manual',enrollmentId:text(t.enrollmentId,200),stepId:text(t.stepId,100),createdAt:date(t.createdAt)||new Date().toISOString()};}
export function cleanConversation(c){if(!object(c))throw new Error('Una conversación no es válida.');const channel=String(c.channel||'');if(!CONV_CHANNELS.includes(channel))throw new Error('Canal de conversación no válido.');const direction=c.direction||'out';if(!['in','out'].includes(direction))throw new Error('Dirección de mensaje no válida.');const body=text(c.text,5000).trim();if(!body)throw new Error('Escribe el mensaje o el resumen de la conversación.');if(!String(c.leadId||'').trim())throw new Error('La conversación necesita un contacto.');return {id:text(c.id||uid(),200),leadId:text(c.leadId,200),channel,direction,at:date(c.at)||new Date().toISOString(),text:body,subject:text(c.subject,200),source:['manual','wa.me','mailto'].includes(c.source)?c.source:'manual'};}
export function cleanEnrollment(e){if(!object(e))throw new Error('Una inscripción no es válida.');if(!inMap(ENROLLMENT_STATUSES,e.status||'active'))throw new Error('Estado de inscripción no válido.');if(!String(e.leadId||'').trim()||!String(e.sequenceId||'').trim())throw new Error('La inscripción necesita contacto y secuencia.');return {id:text(e.id||uid(),200),leadId:text(e.leadId,200),sequenceId:text(e.sequenceId,100),startedAt:date(e.startedAt)||new Date().toISOString(),status:e.status||'active',endedAt:date(e.endedAt),reason:text(e.reason,200),pausedAt:date(e.pausedAt)};}

function quoteNum(v,{min,max,dec,label}){const n=typeof v==='number'?v:Number(String(v??'').trim());if(!Number.isFinite(n)||n<min||n>max)throw new Error(`${label} no es válido.`);const f=10**dec;return Math.round(n*f)/f;}
function cleanItem(it){if(!object(it))throw new Error('Un concepto de la cotización no es válido.');const desc=text(it.desc,300).trim();if(!desc)throw new Error('Cada concepto necesita una descripción.');return {id:text(it.id||uid(),100),desc,qty:quoteNum(it.qty??1,{min:0.001,max:1e6,dec:3,label:'La cantidad'}),price:quoteNum(it.price??0,{min:0,max:1e12,dec:2,label:'El precio'})};}
const STRIPE_HOST=/(^|\.)stripe\.com$/i;
export function validPaymentLink(v){if(!v)return true;try{const u=new URL(v);return u.protocol==='https:'&&STRIPE_HOST.test(u.hostname)&&!/[\u0000- \\]/.test(v);}catch{return false;}}
function cleanSignature(sg){if(sg===undefined||sg===null||sg==='')return null;if(!object(sg))throw new Error('La firma no es válida.');const name=text(sg.name,150).trim();if(!name)throw new Error('La firma necesita el nombre de quien firma.');if(!/^[0-9a-f]{64}$/.test(sg.hash||''))throw new Error('La huella de la firma no es válida.');const image=sg.image?String(sg.image):'';if(image&&(!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(image)||image.length>90000))throw new Error('La imagen de la firma no es válida.');return {name,at:date(sg.at,true),hash:sg.hash,image,method:'firma simple de demostración'};}
export function cleanQuote(q){if(!object(q))throw new Error('Una cotización no es válida.');const status=q.status||'draft';if(!inMap(QUOTE_STATUSES,status))throw new Error('Estado de cotización no válido.');if(!Array.isArray(q.items)||!q.items.length||q.items.length>60)throw new Error('La cotización necesita entre 1 y 60 conceptos.');const currency=q.currency||'MXN';if(!['MXN','USD'].includes(currency))throw new Error('Moneda no válida: usa MXN o USD.');const disc=object(q.discount)?q.discount:{type:'percent',value:0};const dtype=disc.type==='amount'?'amount':'percent';const dvalue=quoteNum(disc.value??0,{min:0,max:dtype==='percent'?100:1e12,dec:2,label:'El descuento'});const link=String(q.paymentLink??'').trim();if(!validPaymentLink(link))throw new Error('El link de pago debe ser un Payment Link de Stripe con https (por ejemplo https://buy.stripe.com/…).');const vu=q.validUntil?String(q.validUntil):'';if(vu&&!dayToISO(vu))throw new Error('La vigencia no es válida.');
 const history=(Array.isArray(q.history)?q.history:[]).slice(-50).map(h=>({at:date(h?.at,true),status:inMap(QUOTE_STATUSES,h?.status)?h.status:'draft',note:text(h?.note,300)}));
 return {id:text(q.id||uid(),200),number:text(q.number,40),leadId:text(q.leadId,200),propertyId:text(q.propertyId,100),title:text(q.title,200),currency,items:q.items.map(cleanItem),discount:{type:dtype,value:dvalue},iva:q.iva===true,validUntil:vu,terms:text(q.terms,5000),notes:text(q.notes,2000),paymentLink:link,status,signature:cleanSignature(q.signature),history,createdAt:date(q.createdAt)||new Date().toISOString(),updatedAt:date(q.updatedAt)||new Date().toISOString()};}
